 require_admin(true);$provider=enum_input('provider',['ai','ranking','keyword','backlink','smtp','razorpay']);$maps=['ai'=>['AI_ENDPOINT','AI_API_KEY','AI_MODEL'],'ranking'=>['RANKING_ENDPOINT','RANKING_API_KEY'],'keyword'=>['KEYWORD_ENDPOINT','KEYWORD_API_KEY'],'backlink'=>['BACKLINK_ENDPOINT','BACKLINK_API_KEY'],'smtp'=>['SMTP_HOST','SMTP_USER','SMTP_PASS','SMTP_FROM','SMTP_PORT'],'razorpay'=>['RAZORPAY_KEY','RAZORPAY_SECRET','RAZORPAY_WEBHOOK_SECRET']];
 $endpoint=input('endpoint',1000);$key=input('key',1000);$secret=input('secret',1000);$extra=input('extra',1000);$clear=isset($_POST['clear']);$updates=[];
