  if($provider==='ai')$updates=['AI_ENDPOINT'=>$endpoint,'AI_API_KEY'=>$key,'AI_MODEL'=>$extra];elseif(in_array($provider,['ranking','keyword','backlink']))$updates=[strtoupper($provider).'_ENDPOINT'=>$endpoint,strtoupper($provider).'_API_KEY'=>$key];elseif($provider==='razorpay')$updates=['RAZORPAY_KEY'=>$key,'RAZORPAY_SECRET'=>$secret,'RAZORPAY_WEBHOOK_SECRET'=>$extra];else{if($extra&&!filter_var($extra,FILTER_VALIDATE_EMAIL))fail('SMTP sender must be an email address.');if($endpoint&&!preg_match('/^[a-z0-9.-]+$/i',$endpoint))fail('Invalid SMTP hostname.');$port=(int)input('port',5,'587');if(!in_array($port,[465,587]))fail('Use encrypted SMTP on port 465 or 587.');$updates=['SMTP_HOST'=>$endpoint,'SMTP_USER'=>$key,'SMTP_PASS'=>$secret,'SMTP_FROM'=>$extra,'SMTP_PORT'=>$port];}$updates=array_filter($updates,fn($v)=>$v!=='');
