 $path=getenv('SEO_CONFIG_FILE')?:ROOT.'/config/local.php';if(!is_file($path)||!is_writable($path))fail('Private configuration is not writable. Update it through your hosting control panel.',503);$lock=fopen(ROOT.'/storage/config.guard','c');if(!$lock||!flock($lock,LOCK_EX))fail('Cannot lock configuration.');$existing=require $path;$new=array_replace($existing,$updates);if(file_put_contents($path,"<?php\nreturn ".var_export($new,true).";\n",LOCK_EX)===false)fail('Unable to save configuration.');flock($lock,LOCK_UN);fclose($lock);audit_log('admin.provider.updated',['provider'=>$provider,'cleared'=>$clear]);json_response([],'Private provider configuration saved');
